import { SettingKey, type SettingKeyType } from './SettingKey';

/**
 * Supported setting types.
 *
 * - `boolean`, `number`, `string`: match the corresponding JS `typeof`.
 * - `object`: a plain JSON object (non-null, non-array). For objects, the
 *   persisted value is *shallow-merged* on top of the default on read, so
 *   that fields added to the default in a later release are transparently
 *   populated for existing users without losing their customizations.
 */
export const SettingType = Object.freeze({
  BOOLEAN: 'boolean',
  NUMBER: 'number',
  STRING: 'string',
  OBJECT: 'object',
  // An array of strings. Unlike `OBJECT`, which is shallow-merged onto the
  // default, an `ARRAY` value is *normalized* against the default array on
  // read (see `sanitize`): unknown entries are dropped and any default
  // entries missing from the stored value are appended, so the array always
  // ends up a permutation of the default's elements.
  ARRAY: 'array',
} as const);

export type SettingTypeValue = (typeof SettingType)[keyof typeof SettingType];

/**
 * A single registry entry for one persistent setting.
 *
 * `validate` receives a value that has already passed the type check, so it
 * can safely cast to the expected primitive/object type.
 */
export interface SchemaEntry {
  type: SettingTypeValue;
  default: unknown;
  validate?: (v: unknown) => boolean;
}

const ALLOWED_HELP_LANGUAGES = ['en', 'it', 'zh'];

// Allowed values for the theme mode setting. 'auto' follows the OS
// `prefers-color-scheme` media query; the other two force a specific
// palette mode.
export const ALLOWED_THEME_MODES = ['auto', 'light', 'dark'];

// Font size bounds for the code editor, in pt.
const MIN_FONT_SIZE = 1;
const MAX_FONT_SIZE = 72;

// Multi-step stride bounds (number of simulation steps the "Multi Step"
// button runs in one click). Mirrors the `<input min/max>` that used to live
// in the Header, but enforced centrally here so the persisted value is
// always in range.
export const MIN_STEP_STRIDE = 1;
export const MAX_STEP_STRIDE = 100000;

// Execution delay bounds, in milliseconds. `0` means "run as fast as
// possible" (the previous behavior). The upper bound is generous enough to
// demonstrate pipeline effects without being able to accidentally lock the
// UI into a multi-minute sleep between tiny batches.
export const MIN_EXECUTION_DELAY_MS = 0;
export const MAX_EXECUTION_DELAY_MS = 5000;

// Resizable-workspace bounds, as a percentage of the workspace size. The
// right widgets column may take 20–60% of the width; the bottom Cycles
// region may take 12–70% of the height. The minimums keep every region
// usable (the code editor never shrinks below 40% width, the upper region
// never below 30% height).
export const MIN_RIGHT_WIDTH_PCT = 20;
export const MAX_RIGHT_WIDTH_PCT = 60;
export const MIN_BOTTOM_HEIGHT_PCT = 12;
export const MAX_BOTTOM_HEIGHT_PCT = 70;

// Shared validator for the L1D / L1I cache configuration objects.
const isPositiveInteger = (v: number) => Number.isInteger(v) && v > 0;
const isValidCacheConfig = (v: unknown) => {
  if (typeof v !== 'object' || v === null) return false;
  const c = v as Record<string, unknown>;
  return (
    isPositiveInteger(c.size as number) &&
    isPositiveInteger(c.blockSize as number) &&
    isPositiveInteger(c.associativity as number)
  );
};

// Hex color (`#RRGGBB`) validator used by the pipeline color settings.
const HEX_COLOR_RE = /^#[0-9a-fA-F]{6}$/;
const isHexColor = (v: unknown) =>
  typeof v === 'string' && HEX_COLOR_RE.test(v);

/**
 * Default colors for the Pipeline widget, mirroring the Swing UI's
 * `IF_COLOR` / `ID_COLOR` / ... `ConfigKey` defaults from `ConfigStore`.
 *
 * The keys here mirror the stage groups drawn by the Pipeline widget; the
 * `Stall` entry is used to highlight pipeline bubbles, which the Swing UI
 * does not render but the Web UI does.
 */
export const DEFAULT_PIPELINE_COLORS = Object.freeze({
  IF: '#ebeb3b', // Swing default rgb(235, 235, 59)
  ID: '#2196f3', // Swing default rgb( 33, 150, 243)
  EX: '#f44336', // Swing default rgb(244,  67,  54)
  MEM: '#4caf50', // Swing default rgb( 76, 175,  80)
  WB: '#ab47bc', // Swing default rgb(171,  71, 188)
  FPAdder: '#008000', // Swing default rgb(  0, 128,   0)
  FPMultiplier: '#008080', // Swing default rgb(  0, 128, 128)
  FPDivider: '#808000', // Swing default rgb(128, 128,   0)
  Stall: '#9e9e9e', // Material grey 500 — Swing has no equivalent.
});

// Validator for the resizable-workspace layout object. Percentages must be
// finite numbers inside their documented bounds; the collapse flags must be
// booleans. Out-of-range or malformed values fall back to the default.
const inRange = (v: unknown, min: number, max: number) =>
  typeof v === 'number' && Number.isFinite(v) && v >= min && v <= max;
const isValidWorkspaceLayout = (v: unknown) => {
  if (typeof v !== 'object' || v === null) return false;
  const l = v as Record<string, unknown>;
  return (
    inRange(l.rightWidthPct, MIN_RIGHT_WIDTH_PCT, MAX_RIGHT_WIDTH_PCT) &&
    inRange(l.bottomHeightPct, MIN_BOTTOM_HEIGHT_PCT, MAX_BOTTOM_HEIGHT_PCT) &&
    typeof l.rightCollapsed === 'boolean' &&
    typeof l.bottomCollapsed === 'boolean'
  );
};

/**
 * Stable ids for the reorderable dashboard cards in the Simulator's right
 * panel, in their default display order. These are the *only* ids the
 * `WIDGET_ORDER` setting ever contains — the `Issues` card is not part of
 * the reorderable set (it appears/disappears with parsing errors and is
 * always pinned above the reorderable cards).
 */
export const DEFAULT_WIDGET_ORDER = Object.freeze([
  'stats',
  'pipeline',
  'registers',
  'memory',
  'stdout',
]);

export type DashboardWidgetId = (typeof DEFAULT_WIDGET_ORDER)[number];

// A valid stored widget order is an array of strings with no duplicates.
// Unknown ids and missing ids are *not* rejected here — they are normalized
// (dropped / appended) by `sanitize`'s ARRAY branch, so that adding a future
// widget or renaming/removing one never throws away an otherwise-valid saved
// layout.
const isValidWidgetOrder = (v: unknown) => {
  if (!Array.isArray(v)) return false;
  if (!v.every((entry) => typeof entry === 'string')) return false;
  return new Set(v).size === v.length;
};

const isValidPipelineColors = (v: unknown) => {
  if (typeof v !== 'object' || v === null) return false;
  const colors = v as Record<string, unknown>;
  return Object.keys(DEFAULT_PIPELINE_COLORS).every(
    (k) => colors[k] === undefined || isHexColor(colors[k]),
  );
};

/**
 * The single, canonical registry of all locally-persisted settings.
 *
 * Each entry describes:
 *   - `type`:     one of `SettingType.*`. Used to validate the stored value.
 *   - `default`:  the value returned when nothing is persisted, or when the
 *                 persisted value is missing / has the wrong type / fails
 *                 `validate`. This is the *documented* default.
 *   - `validate`: (optional) extra predicate called after the type check. If
 *                 it returns `false`, the stored value is discarded and the
 *                 default is used instead (a warning is logged).
 *
 * This mirrors the `defaults` map and getter signatures in the Java
 * `ConfigStore`: everything a user can tweak has exactly one row here, with
 * its type and its default value.
 */
export const SETTINGS_SCHEMA: Readonly<Record<string, SchemaEntry>> =
  Object.freeze({
    [SettingKey.VI_MODE]: {
      type: SettingType.BOOLEAN,
      default: false,
    },
    [SettingKey.FONT_SIZE]: {
      type: SettingType.NUMBER,
      default: 14,
      validate: (v) =>
        typeof v === 'number' &&
        Number.isFinite(v) &&
        v >= MIN_FONT_SIZE &&
        v <= MAX_FONT_SIZE,
    },
    [SettingKey.ACCORDION_ALERTS]: {
      type: SettingType.BOOLEAN,
      default: true,
    },
    [SettingKey.EXPANDED_ACCORDIONS]: {
      type: SettingType.OBJECT,
      // Defaults follow the simulator's primary purpose: a first-time visitor
      // should see the pipeline, registers, and stats — the headline features
      // of a CPU simulator — without having to scroll-and-click. Memory and
      // standard output stay collapsed by default to keep the right rail
      // compact on small screens; the change-indicator dot still draws
      // attention to them when something changes.
      //
      // Cache configuration and general settings used to live here as
      // collapsible panels too, but now live in the Settings dialog (opened
      // via the gear button in the header), so they no longer need an
      // expand/collapse state.
      //
      // This is only the *default* — every user-driven expand/collapse is
      // persisted to localStorage via `useSetting`, so a returning user always
      // sees the layout they last left.
      default: {
        stats: true,
        pipeline: true,
        registers: true,
        memory: false,
        stdout: false,
      },
    },
    [SettingKey.CACHE_L1D]: {
      type: SettingType.OBJECT,
      default: {
        size: 1024,
        blockSize: 16,
        associativity: 1,
      },
      validate: isValidCacheConfig,
    },
    [SettingKey.CACHE_L1I]: {
      type: SettingType.OBJECT,
      default: {
        size: 1024,
        blockSize: 16,
        associativity: 1,
      },
      validate: isValidCacheConfig,
    },
    [SettingKey.HELP_LANGUAGE]: {
      type: SettingType.STRING,
      default: 'en',
      validate: (v) =>
        typeof v === 'string' && ALLOWED_HELP_LANGUAGES.includes(v),
    },
    [SettingKey.FORWARDING]: {
      type: SettingType.BOOLEAN,
      // Matches the Java `ConfigStore` default for `ConfigKey.FORWARDING`.
      default: false,
    },
    [SettingKey.DELAY_SLOT]: {
      type: SettingType.BOOLEAN,
      // Matches the Java `ConfigStore` default for `ConfigKey.DELAY_SLOT`.
      // Off by default to preserve the simulator's classic semantics where
      // the instruction sequentially after a branch is squashed.
      default: false,
    },
    [SettingKey.STEP_STRIDE]: {
      type: SettingType.NUMBER,
      // Matches the legacy `multiStepCount` default that used to live in
      // `Header.js` local state.
      default: 500,
      validate: (v) =>
        typeof v === 'number' &&
        Number.isInteger(v) &&
        v >= MIN_STEP_STRIDE &&
        v <= MAX_STEP_STRIDE,
    },
    [SettingKey.EXECUTION_DELAY_MS]: {
      type: SettingType.NUMBER,
      // 0 means "no artificial delay between batches", which is the pre-existing
      // behavior.
      default: 0,
      validate: (v) =>
        typeof v === 'number' &&
        Number.isFinite(v) &&
        v >= MIN_EXECUTION_DELAY_MS &&
        v <= MAX_EXECUTION_DELAY_MS,
    },
    [SettingKey.EDITOR_CODE]: {
      type: SettingType.STRING,
      // Use an empty string as the sentinel for "user hasn't customized the editor
      // yet". This avoids baking today's SampleProgram into localStorage on the
      // very first visit, which would prevent a future sample update from being
      // visible to users who never edited the editor.  Simulator.js maps '' back
      // to the current SampleProgram when rendering.
      default: '',
    },
    [SettingKey.PIPELINE_COLORS]: {
      type: SettingType.OBJECT,
      default: { ...DEFAULT_PIPELINE_COLORS },
      validate: isValidPipelineColors,
    },
    [SettingKey.THEME_MODE]: {
      type: SettingType.STRING,
      // 'auto' follows the OS-level `prefers-color-scheme` media query, which
      // matches the pre-existing behavior. 'light' and 'dark' force the
      // corresponding MUI palette mode regardless of the OS setting.
      default: 'auto',
      validate: (v) => typeof v === 'string' && ALLOWED_THEME_MODES.includes(v),
    },
    [SettingKey.WORKSPACE_LAYOUT]: {
      type: SettingType.OBJECT,
      default: {
        rightWidthPct: 34,
        bottomHeightPct: 30,
        rightCollapsed: false,
        bottomCollapsed: false,
      },
      validate: isValidWorkspaceLayout,
    },
    [SettingKey.WIDGET_ORDER]: {
      type: SettingType.ARRAY,
      default: [...DEFAULT_WIDGET_ORDER],
      validate: isValidWidgetOrder,
    },
  });

/**
 * Return true if `value` matches the declared `type`.
 */
function matchesType(value: unknown, type: SettingTypeValue): boolean {
  switch (type) {
    case SettingType.BOOLEAN:
      return typeof value === 'boolean';
    case SettingType.NUMBER:
      return typeof value === 'number' && Number.isFinite(value);
    case SettingType.STRING:
      return typeof value === 'string';
    case SettingType.OBJECT:
      return (
        typeof value === 'object' && value !== null && !Array.isArray(value)
      );
    case SettingType.ARRAY:
      return Array.isArray(value);
    default:
      return false;
  }
}

/**
 * Look up the schema entry for `key`, or throw if `key` is not registered.
 * Using an unknown key is always a programmer error, never user data.
 */
export function getSchema(key: string): SchemaEntry {
  const entry = SETTINGS_SCHEMA[key];
  if (!entry) {
    throw new Error(`Unknown setting key: "${key}"`);
  }
  return entry;
}

/**
 * Validate a raw value against the schema entry for `key`.
 *
 * Returns the sanitized value to use:
 *  - the default if `raw` is `undefined` or fails the type/validate checks;
 *  - for `object` settings, a shallow merge of the default with the raw
 *    object, so keys added to the default in later versions are populated;
 *  - otherwise `raw` itself.
 *
 * Never throws: invalid data is logged and silently replaced with the default,
 * so persistence can't break the simulator.
 */
export function sanitize(key: string, raw: unknown): unknown {
  const { type, default: defaultValue, validate } = getSchema(key);

  if (raw === undefined) {
    return defaultValue;
  }

  if (!matchesType(raw, type)) {
    console.warn(
      `settings: stored value for "${key}" has wrong type (expected ${type}), ` +
        'falling back to default.',
    );
    return defaultValue;
  }

  if (validate && !validate(raw)) {
    console.warn(
      `settings: stored value for "${key}" failed validation, ` +
        'falling back to default.',
    );
    return defaultValue;
  }

  if (type === SettingType.OBJECT) {
    // Shallow-merge default under stored value so new default keys surface.
    return { ...(defaultValue as object), ...(raw as object) };
  }

  if (type === SettingType.ARRAY) {
    // Normalize against the default array: drop entries that are no longer
    // known (e.g. a widget removed in a later release), then append any
    // default entries missing from the stored value (e.g. a widget added in
    // a later release), preserving their relative order from the default.
    // This keeps a user's saved layout intact across simulator updates
    // instead of discarding it wholesale.
    const storedArr = raw as string[];
    const defaultArr = defaultValue as string[];
    const known = new Set(defaultArr);
    const filtered = storedArr.filter((entry) => known.has(entry));
    const present = new Set(filtered);
    const missing = defaultArr.filter((entry) => !present.has(entry));
    return [...filtered, ...missing];
  }

  return raw;
}

// ---------------------------------------------------------------------------
// SettingValueMap — per-key type inference for useSetting<K>
// ---------------------------------------------------------------------------

/**
 * The expanded-accordions object that controls which Simulator panels are
 * open by default and after user interaction.
 */
export interface ExpandedAccordions {
  stats: boolean;
  pipeline: boolean;
  registers: boolean;
  memory: boolean;
  stdout: boolean;
}

/**
 * L1 cache configuration parameters (L1D and L1I share the same shape).
 */
export interface CacheConfig {
  size: number;
  blockSize: number;
  associativity: number;
}

/**
 * Per-stage pipeline colours (hex `#RRGGBB` strings).
 * Mirrors the keys in `DEFAULT_PIPELINE_COLORS`.
 */
export interface PipelineColors {
  IF: string;
  ID: string;
  EX: string;
  MEM: string;
  WB: string;
  FPAdder: string;
  FPMultiplier: string;
  FPDivider: string;
  Stall: string;
}

/** Allowed values for the `THEME_MODE` setting. */
export type ThemeMode = 'auto' | 'light' | 'dark';

/**
 * Geometry of the resizable workspace: the width of the right widgets column
 * and the height of the bottom Cycles region (each as a percentage of the
 * workspace), plus whether either region is collapsed to a thin bar.
 */
export interface WorkspaceLayout {
  rightWidthPct: number;
  bottomHeightPct: number;
  rightCollapsed: boolean;
  bottomCollapsed: boolean;
}

/**
 * Maps every `SettingKeyType` string value to its concrete TypeScript value
 * type.  This is the source of truth used by `useSetting<K>` to give call
 * sites a precisely-typed `[value, setValue, reset]` tuple without any casts.
 *
 * Adding a new setting: add a row here and a matching row in `SETTINGS_SCHEMA`.
 */
export interface SettingValueMap extends Record<SettingKeyType, unknown> {
  // Editor / general UI
  viMode: boolean;
  fontSize: number;
  accordionAlerts: boolean;
  expandedAccordions: ExpandedAccordions;
  // Cache
  'cache.l1d': CacheConfig;
  'cache.l1i': CacheConfig;
  // CPU
  forwarding: boolean;
  delaySlot: boolean;
  // Execution
  stepStride: number;
  executionDelayMs: number;
  // Help dialog
  'help.language': string;
  // Editor content
  editorCode: string;
  // Pipeline widget colours
  pipelineColors: PipelineColors;
  // UI theme
  themeMode: ThemeMode;
  // Resizable-workspace geometry
  workspaceLayout: WorkspaceLayout;
  // Dashboard card drag-and-drop order
  widgetOrder: DashboardWidgetId[];
}
